#include "harness_start.bash"

# A regeneration that produces the bytes already on disk must not move
# the output's mtime, because everything downstream of a GENERATE is
# keyed on that mtime and nothing downstream has any other way to ask
# whether the generated file still says what it said.
#
# The input shape this exists for is a file that is REWRITTEN rather
# than changed.  A script whose answer is a function of its inputs'
# content has inputs whose mtime can move on its own: a cache being
# repacked, a lock file being rewritten, an archive being unpacked over
# itself.  make cannot tell that from an edit -- mtime is all it has --
# so the rule runs, and whether the rebuild stops there or runs all the
# way through the consumers is decided by what the recipe does with an
# answer it has seen before.
#
# Measured in the tree that vendors pconfigure, which is why the
# threshold for caring is low.  Its glibc and xfstests conformance
# harnesses each watch a stamp whose body is `git rev-parse HEAD` for a
# submodule, declared against .git's HEAD, the branch ref and
# packed-refs; `git pack-refs` and the auto-gc any `git fetch` may
# trigger rewrite packed-refs for a revision that did not move.  The
# stamp regenerated byte-identical with a fresh mtime and an hours-long
# conformance suite re-ran to produce the verdicts it had already
# produced.  The declaration cannot be narrowed out of it either: a
# branch's tip lives in the loose ref until it is packed and in
# packed-refs afterwards, so watching one and not the other misses the
# move itself.
#
# Two sources, as in generate-input-change-recompiles-consumers.bash:
# "other.c" reads nothing generated, so a build that recompiles it is
# propagating further than the graph says, and app.c reads the header so
# its recompilation is the cascade being measured.
#
# The script's answer deliberately ignores everything about the input
# but its first line, which is what makes "touch the input" and "append
# to the input" two different experiments rather than one.  The first
# asks whether mtime alone cascades; the second asks whether a real
# change still does, which is the half that stops the fix from being
# "never write the file".
#
# What this does NOT claim is that such a rule settles.  It does not,
# and cannot: the target stays older than the prerequisite that was
# touched, so make asks again on every build until something changes the
# output.  That is asserted below rather than worked around, because an
# unasserted limitation is indistinguishable from a bug and the next
# reader will "fix" it -- and because the thing it costs is one run of a
# script that is already a prerequisite of everything it feeds, against
# a cascade whose cost is the consumers'.

mkdir -p src

cat >Configfile <<EOF
LANGUAGES += c

GENERATE  += gen.h

BINARIES  += app
SOURCES   += app.c
SOURCES   += other.c
EOF

cat >src/input.txt <<EOF
42
EOF

cat >src/gen.h.proc <<'EOF'
#!/bin/bash
case "$1" in
--deps)     echo "src/input.txt" ;;
--generate) echo "#define ANSWER $(head -n 1 src/input.txt)" ;;
esac
EOF
chmod +x src/gen.h.proc

cat >src/app.c <<'EOF'
  #include "gen.h"
  #include <stdio.h>
int main(void) { printf("%d\n", ANSWER); return 0; }
EOF

cat >src/other.c <<'EOF'
int other(void) { return 9; }
EOF

$PTEST_BINARY $PCONFIGURE_ARGS
cat Makefile
timeout 60 make $MAKE_ARGS > first.out 2>&1 || { cat first.out; exit 1; }
cat first.out
test "$(./bin/app)" = "42"

# A build with nothing to do is the ordinary answer, which is what makes
# the builds after the two edits below mean anything at all.
timeout 60 make $MAKE_ARGS > settled.out 2>&1 || { cat settled.out; exit 1; }
cat settled.out
grep -q "Nothing to be done" settled.out

##############################################################################
# The input is rewritten rather than changed                                 #
##############################################################################
# `touch` is the whole of `git pack-refs` as far as this rule can tell:
# the declared prerequisite comes back newer and says the same thing.
sleep 2
touch src/input.txt

# The mtime the assertion is about.  Read with "test -nt"/"test -ot"
# against a witness rather than with stat(1), whose output format and
# option letters are not the same program on a mac as on a GNU box --
# and "-nt" is the comparison make itself makes, so an assertion written
# this way is asking make's question rather than one next to it.
touch witness
test obj/proc/gen.h -ot witness

timeout 60 make $MAKE_ARGS > second.out 2>&1 || { cat second.out; exit 1; }
cat second.out

# The script DID run: the prerequisite is newer, so make asked, and a
# recipe that was never consulted would be a different fix -- one that
# had stopped watching the input.  This is the line that says the
# suppression lives in the recipe rather than in the dependency graph.
grep -q "^GEN	gen.h$" second.out

# The output still holds the same bytes ...
grep -q "define ANSWER 42" obj/proc/gen.h

# ... and, the point of all this, it is still the file it was.  A mv
# would have made it newer than the witness taken before the build.
test obj/proc/gen.h -ot witness

# So nothing downstream was rebuilt: not the consumer of the header, not
# the link, and not the bystander either.
if grep -q "^CC	app.c$" second.out
then
    exit 1
fi
if grep -q "^LD	app$" second.out
then
    exit 1
fi
if grep -q "^CC	other.c$" second.out
then
    exit 1
fi

# And no temporary was left behind.  The suppressed branch has to clean
# up after itself: a ".tmp" sitting next to the output is a file the
# next run's cmp would be reading if the plumbing were ever rearranged.
test ! -e obj/proc/gen.h.tmp

##############################################################################
# It does not settle, and that is the trade rather than an oversight        #
##############################################################################
# The output is older than the input that was touched, so make keeps
# asking -- forever, until something changes the answer.  The script
# runs again and the consumers still do not.  If a later change makes
# this build report "Nothing to be done", the suppression has grown a
# witness file and this block is the thing to rewrite.
timeout 60 make $MAKE_ARGS > third.out 2>&1 || { cat third.out; exit 1; }
cat third.out
grep -q "^GEN	gen.h$" third.out
test obj/proc/gen.h -ot witness
if grep -q "^CC	app.c$" third.out
then
    exit 1
fi

##############################################################################
# A real change is still heard, which is what stops "never write it"       #
##############################################################################
# The first line is what the script reads, so the append above would
# have been invisible; this changes the answer.  Everything the block
# above refused to do has to happen here, or the fix is just a rule that
# has stopped writing its target.
sleep 2
echo 43 > src/input.txt

timeout 60 make $MAKE_ARGS > fourth.out 2>&1 || { cat fourth.out; exit 1; }
cat fourth.out
grep -q "^GEN	gen.h$" fourth.out
grep -q "define ANSWER 43" obj/proc/gen.h
grep -q "^CC	app.c$" fourth.out
grep -q "^LD	app$" fourth.out
test "$(./bin/app)" = "43"

# The bystander is still a bystander, so what moved is the dependency
# edge and not the whole tree.
if grep -q "^CC	other.c$" fourth.out
then
    exit 1
fi

# And a genuine write DOES settle: the target is newer than the input
# again, so make has nothing left to ask.  That is what says the
# suppressed branch is the only one that leaves the mtime alone.
timeout 60 make $MAKE_ARGS > fifth.out 2>&1 || { cat fifth.out; exit 1; }
cat fifth.out
grep -q "Nothing to be done" fifth.out

exit 0
